import { supabase } from '../../config/supabase.js';
import { sendError, mapDbError } from '../../utils/respond.js';

export const createProduct = async (req, res) => {
    try {
        const { seller_id, title, description, price, category, location, condition } = req.body;
        const files = req.files;

        if (!files || files.length === 0) {
            return res.status(400).json({ error: 'At least one image is required.' });
        }
        if (!title || !price || !category) {
            return res.status(400).json({ error: 'Title, price, and category are required.' });
        }

        // 1. Securely fetch the user's university_id to enforce multi-tenant isolation
        const { data: user, error: userError } = await supabase
            .from('users')
            .select('university_id')
            .eq('id', seller_id)
            .single();

        if (userError || !user) throw new Error('Seller not found.');
        const university_id = user.university_id;

        // 2. Upload multiple images to Supabase 'products' bucket
        const imageUrls = [];
        for (const file of files) {
            const fileExt = file.originalname.split('.').pop();
            // Create a unique filename: sellerId-timestamp-randomString.ext
            const fileName = `${seller_id}-${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;

            const { error: uploadError } = await supabase.storage
                .from('products')
                .upload(fileName, file.buffer, {
                    contentType: file.mimetype,
                    upsert: false
                });

            if (uploadError) throw uploadError;

            // Get public URL
            const { data: { publicUrl } } = supabase.storage
                .from('products')
                .getPublicUrl(fileName);

            imageUrls.push(publicUrl);
        }

        // 3. Insert the new product into the database
        const { data: product, error: insertError } = await supabase
            .from('products')
            .insert([{
                seller_id,
                university_id,
                title,
                description,
                price: Number(price),
                category,
                location,  
                condition, 
                image_urls: imageUrls,
                status: 'available'
            }])
            .select()
            .single();

        if (insertError) throw insertError;

        res.status(201).json({
            message: 'Product listed successfully!',
            product
        });

    } catch (error) {
        console.error('Create Product Error:', error);
        res.status(500).json({ error: 'Failed to create product listing.' });
    }
};

export const updateProduct = async (req, res) => {
    try {
        const { id } = req.params;

        // 🔒 OWNERSHIP (plan §1.6 Bug 1 / CURRENT_STATE audit).
        //
        // This handler used to take `id` straight from the URL and UPDATE on it
        // with no actor at all — anyone who knew a listing's uuid could rewrite
        // its title, price and status on any campus.
        //
        // The owner is `req.user.id` from the Bearer token verified by
        // requireAuth, and nothing else. There is deliberately no seller_id in
        // the body to compare against: a caller-supplied one would be exactly
        // the hole this closes.
        const { data: existing, error: lookupError } = await supabase
            .from('products')
            .select('seller_id')
            .eq('id', id)
            .maybeSingle();

        // maybeSingle, not single: "no such listing" is a 404, not a 500.
        if (lookupError) {
            console.error('Update Product Error (ownership lookup):', lookupError);
            return sendError(res, 500, 'INTERNAL_ERROR', {
                message: 'Failed to update product.',
            });
        }

        if (!existing) {
            return sendError(res, 404, 'NOT_FOUND', {
                message: 'That listing no longer exists.',
            });
        }

        if (existing.seller_id !== req.user.id) {
            return sendError(res, 403, 'FORBIDDEN', {
                message: 'You can only edit your own listings.',
            });
        }

        // 🩹 PARTIAL UPDATE (plan §1.6 Bug 2).
        //
        // This payload used to be built unconditionally from seven destructured
        // body fields. `JSON.stringify` drops the `undefined` ones on its own, so
        // six of them were harmless — but `price` went through `Number(price)`
        // first, and `Number(undefined)` is `NaN`, which serializes to `null`.
        // `products.price` is NOT NULL, so every body without a price hit 23502
        // and the seller got a generic 500. A title-only edit was impossible.
        //
        // The payload is now built from the keys the caller actually SENT.
        // Presence is tested with hasOwnProperty, not truthiness: `description: ''`
        // and `price: 0` are legitimate edits and must survive.
        const UPDATABLE = ['title', 'description', 'price', 'category', 'location', 'condition', 'status'];
        const sent = (field) => Object.prototype.hasOwnProperty.call(req.body, field);

        const updates = {};
        for (const field of UPDATABLE) {
            if (sent(field)) updates[field] = req.body[field];
        }

        // Price is the only field that is coerced, so it is the only one that can
        // become NaN. Validate before it reaches the column rather than letting
        // Postgres reject it as an opaque 500. `null`, `''` and booleans are
        // rejected explicitly: `Number()` maps all three onto a finite number.
        if (sent('price')) {
            const raw = req.body.price;
            const parsed = (raw === null || raw === '' || typeof raw === 'boolean')
                ? NaN
                : Number(raw);

            if (!Number.isFinite(parsed) || parsed < 0) {
                return sendError(res, 400, 'INVALID_PRICE', {
                    message: 'Price must be a number greater than or equal to 0.',
                });
            }
            updates.price = parsed;
        }

        // An UPDATE with no columns is a PostgREST error, not a no-op — refuse it
        // here so the caller gets a code instead of a leaked driver message.
        if (Object.keys(updates).length === 0) {
            return sendError(res, 400, 'MISSING_FIELDS', {
                message: 'Send at least one field to update.',
            });
        }

        // Update the product in the database
        const { data, error } = await supabase
            .from('products')
            .update(updates)
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;

        res.status(200).json({
            message: 'Product updated successfully',
            product: data
        });
    } catch (error) {
        console.error('Update Product Error:', error);

        // A constraint violation is the caller's input, not our outage. Route the
        // two codes `mapDbError` recognises through it so they surface as 400s;
        // anything else keeps the documented INTERNAL_ERROR envelope.
        if (error?.code === '23505' || error?.code === '23503') {
            return mapDbError(res, error);
        }

        return sendError(res, 500, 'INTERNAL_ERROR', {
            message: 'Failed to update product.',
        });
    }
};

export const deleteProduct = async (req, res) => {
    try {
        const { id } = req.params;

        // 🔒 OWNERSHIP (plan §1.6 Bug 1). Same hole as updateProduct, same fix,
        // and worse in effect: an unauthenticated DELETE on a known uuid
        // destroyed any listing on any campus, cascading to its comments,
        // likes and saves.
        const { data: existing, error: lookupError } = await supabase
            .from('products')
            .select('seller_id')
            .eq('id', id)
            .maybeSingle();

        if (lookupError) {
            console.error('Delete Product Error (ownership lookup):', lookupError);
            return sendError(res, 500, 'INTERNAL_ERROR', {
                message: 'Failed to delete product.',
            });
        }

        if (!existing) {
            return sendError(res, 404, 'NOT_FOUND', {
                message: 'That listing no longer exists.',
            });
        }

        if (existing.seller_id !== req.user.id) {
            return sendError(res, 403, 'FORBIDDEN', {
                message: 'You can only delete your own listings.',
            });
        }

        // Delete the product from the database
        // Note: For a production app, you might also want to delete the images from the Supabase storage bucket here to save space.
        const { error } = await supabase
            .from('products')
            .delete()
            .eq('id', id);

        if (error) throw error;

        res.status(200).json({ message: 'Product deleted successfully' });
    } catch (error) {
        console.error('Delete Product Error:', error);
        return sendError(res, 500, 'INTERNAL_ERROR', {
            message: 'Failed to delete product.',
        });
    }
};

export const getProducts = async (req, res) => {
    try {
        const { university_id, user_id } = req.query;

        if (!university_id) {
            return res.status(400).json({ error: 'university_id query parameter is required.' });
        }

        // 1. Fetch products for the requested campus
        const { data: products, error } = await supabase
            .from('products')
            .select(`
                *,
                seller:users!seller_id(id, full_name, avatar_url)
            `)
            .eq('university_id', university_id)
            .eq('status', 'available')
            .order('created_at', { ascending: false });

        if (error) throw error;

        // 2. If a user is logged in, attach their specific 'liked' and 'saved' statuses
        if (user_id && products.length > 0) {
            const productIds = products.map(p => p.id);
            
            // Run both queries in parallel for performance
            const [likesRes, savesRes] = await Promise.all([
                supabase.from('product_likes').select('product_id').eq('user_id', user_id).in('product_id', productIds),
                supabase.from('product_saves').select('product_id').eq('user_id', user_id).in('product_id', productIds)
            ]);

            // Convert to Sets for instant O(1) lookups
            const likedSet = new Set(likesRes.data?.map(l => l.product_id) || []);
            const savedSet = new Set(savesRes.data?.map(s => s.product_id) || []);

            products.forEach(p => {
                p.is_liked = likedSet.has(p.id);
                p.is_saved = savedSet.has(p.id);
            });
        }

        res.status(200).json({ products });
    } catch (error) {
        console.error('Get Products Error:', error);
        res.status(500).json({ error: 'Failed to fetch marketplace feed.' });
    }
};

export const getProductById = async (req, res) => {
    try {
        const { id } = req.params;
        const { user_id } = req.query; 

        // 1. Fetch Product + Seller + ALL Comments (Notice the explicit !comments_user_id_fkey)
        const { data: product, error } = await supabase
            .from('products')
            .select(`
                *,
                seller:users!seller_id(id, full_name, avatar_url, qualification, year_of_study),
                comments(
                    id, 
                    content, 
                    created_at, 
                    upvotes, 
                    downvotes, 
                    parent_comment_id,
                    user:users!comments_user_id_fkey(id, full_name, avatar_url)
                )
            `)
            .eq('id', id)
            .order('created_at', { foreignTable: 'comments', ascending: false }) 
            .single();

        if (error) throw error;

        // 2. Fetch user's specific interaction states
        if (user_id) {
            const [likesRes, savesRes, votesRes] = await Promise.all([
                supabase.from('product_likes').select('product_id').eq('user_id', user_id).eq('product_id', id).single(),
                supabase.from('product_saves').select('product_id').eq('user_id', user_id).eq('product_id', id).single(),
                supabase.from('comment_votes').select('comment_id, vote_value').eq('user_id', user_id).in('comment_id', product.comments.map(c => c.id))
            ]);

            product.is_liked = !!likesRes.data;
            product.is_saved = !!savesRes.data;

            const userVotes = {};
            if (votesRes.data) {
                votesRes.data.forEach(v => {
                    userVotes[v.comment_id] = v.vote_value;
                });
            }
            
            product.comments.forEach(c => {
                c.user_vote = userVotes[c.id] || 0;
            });
        }

        // 3. Increment the view metric via the RPC
        await supabase.rpc('increment_product_views', { product_id: id });

        res.status(200).json({ product });
    } catch (error) {
        console.error('Get Product By ID Error:', error);
        res.status(500).json({ error: 'Failed to fetch product details.' });
    }
};


/**
 * Minimal, read-only product data for link previews (Open Graph cards).
 *
 * Deliberately NOT getProductById: that endpoint increments the view counter
 * and joins every comment, so using it here would inflate view counts on every
 * crawler hit and over-fetch badly for a card that shows four fields.
 */
export const getProductMeta = async (req, res) => {
    try {
        const { id } = req.params;

        const { data: product, error } = await supabase
            .from('products')
            .select(`
                id, title, description, price, condition, image_urls, status,
                seller:users!seller_id(full_name),
                university:universities!university_id(name)
            `)
            .eq('id', id)
            .single();

        if (error || !product) {
            return res.status(404).json({ error: 'Product not found.' });
        }

        // Cacheable: previews are crawled repeatedly and the data is public.
        res.set('Cache-Control', 'public, max-age=300, s-maxage=300');
        res.status(200).json({
            product: {
                id: product.id,
                title: product.title,
                description: product.description,
                price: product.price,
                condition: product.condition,
                status: product.status,
                image: product.image_urls?.[0] || null,
                seller_name: product.seller?.full_name || null,
                university_name: product.university?.name || null,
            },
        });
    } catch (error) {
        console.error('Get Product Meta Error:', error);
        res.status(500).json({ error: 'Failed to fetch product meta.' });
    }
};

/**
 * 🔒 Guard for every same-campus INTERACTION on a listing (plan §1.6 Bug 2).
 *
 * Yahora's product rule is **browse across campuses, interact only on your
 * own**. `getProducts` is deliberately cross-campus, so a student can see a
 * listing from another university — but liking or saving it was allowed too,
 * which turned a read-only browse into an interaction the rule forbids.
 *
 * Returns `null` when the caller may proceed. Otherwise it has already sent
 * the response, and the caller must return immediately.
 *
 * Both reads are independent, so they cost one round trip rather than two.
 */
async function blockCrossCampusInteraction(req, res, productId, label) {
    const [productRes, meRes] = await Promise.all([
        supabase.from('products').select('university_id').eq('id', productId).maybeSingle(),
        supabase.from('users').select('university_id').eq('id', req.user.id).maybeSingle(),
    ]);

    if (productRes.error || meRes.error) {
        console.error(`${label} Error (campus lookup):`, productRes.error || meRes.error);
        sendError(res, 500, 'INTERNAL_ERROR');
        return true;
    }

    if (!productRes.data) {
        sendError(res, 404, 'NOT_FOUND', { message: 'That listing no longer exists.' });
        return true;
    }

    if (!meRes.data) {
        sendError(res, 404, 'NOT_FOUND', { message: 'No profile exists for this account.' });
        return true;
    }

    const productCampus = productRes.data.university_id;
    const myCampus      = meRes.data.university_id;

    // A NULL on either side is treated as a mismatch, not as a pass. Products
    // always carry a campus, but `handle_new_user` (migration 005) creates a
    // user row with university_id NULL when the email domain is unknown — and
    // "I could not establish that you are on this campus" must fail closed.
    // No real student is affected: every account created through requestOtp
    // has a validated domain and therefore a campus.
    if (!productCampus || !myCampus || productCampus !== myCampus) {
        sendError(res, 403, 'CROSS_CAMPUS_INTERACTION_BLOCKED', {
            message: 'You can only interact with listings on your own campus.',
        });
        return true;
    }

    return false;
}

export const toggleLikeProduct = async (req, res) => {
    try {
        const { id: product_id } = req.params;

        // 🔒 IDENTITY. Was `req.body.user_id` — forgeable, so anyone could like
        // or unlike as any student. It comes from the verified token now, and a
        // `user_id` in the body is ignored in silence: rejecting it would only
        // tell an attacker the parameter used to work.
        const user_id = req.user.id;

        if (await blockCrossCampusInteraction(req, res, product_id, 'Toggle Like')) return;

        const { data: existingLike } = await supabase
            .from('product_likes')
            .select('*')
            .eq('user_id', user_id)
            .eq('product_id', product_id)
            .single();

        if (existingLike) {
            // Deleting the row will now AUTOMATICALLY fire the trigger and decrement the count!
            await supabase.from('product_likes').delete().match({ user_id, product_id });
            res.status(200).json({ message: 'Product unliked', is_liked: false });
        } else {
            // Inserting the row will now AUTOMATICALLY fire the trigger and increment the count!
            await supabase.from('product_likes').insert([{ user_id, product_id }]);
            res.status(200).json({ message: 'Product liked', is_liked: true });
        }
    } catch (error) {
        console.error('Toggle Like Error:', error);
        return sendError(res, 500, 'INTERNAL_ERROR', {
            message: 'Failed to toggle like status.',
        });
    }
};

export const toggleSaveProduct = async (req, res) => {
    try {
        const { id: product_id } = req.params;

        // 🔒 IDENTITY — same as toggleLikeProduct above.
        const user_id = req.user.id;

        if (await blockCrossCampusInteraction(req, res, product_id, 'Toggle Save')) return;

        const { data: existingSave } = await supabase
            .from('product_saves')
            .select('*')
            .eq('user_id', user_id)
            .eq('product_id', product_id)
            .single();

        if (existingSave) {
            await supabase.from('product_saves').delete().match({ user_id, product_id });
            res.status(200).json({ message: 'Product removed from wishlist', is_saved: false });
        } else {
            await supabase.from('product_saves').insert([{ user_id, product_id }]);
            res.status(200).json({ message: 'Product saved to wishlist', is_saved: true });
        }
    } catch (error) {
        console.error('Toggle Save Error:', error);
        return sendError(res, 500, 'INTERNAL_ERROR', {
            message: 'Failed to toggle save status.',
        });
    }
};


export const addComment = async (req, res) => {
    try {
        const { id: product_id } = req.params;
        const { user_id, content, parent_comment_id } = req.body;

        const { data: user, error: userError } = await supabase
            .from('users')
            .select('university_id')
            .eq('id', user_id)
            .single();
        
        if (userError || !user) throw new Error('User not found.');

        // Insert and fetch back using the explicit join
        const { data: comment, error } = await supabase
            .from('comments')
            .insert([{
                product_id,
                user_id,
                university_id: user.university_id,
                content,
                parent_comment_id: parent_comment_id || null
            }])
            .select(`
                id, content, created_at, upvotes, downvotes, parent_comment_id,
                user:users!comments_user_id_fkey(id, full_name, avatar_url)
            `)
            .single();

        if (error) throw error;
        
        res.status(201).json({ message: 'Comment added successfully', comment });
    } catch (error) {
        console.error('Add Comment Error:', error);
        res.status(500).json({ error: 'Failed to post comment.' });
    }
};

export const toggleCommentVote = async (req, res) => {
    try {
        const { commentId } = req.params;
        const { user_id, vote_value } = req.body; // Expects 1 (upvote) or -1 (downvote)

        if (![1, -1].includes(vote_value)) {
            return res.status(400).json({ error: 'Invalid vote value. Must be 1 or -1.' });
        }

        // Trigger the Smart RPC we built in Phase 1
        const { error } = await supabase.rpc('toggle_comment_vote', {
            p_comment_id: commentId,
            p_user_id: user_id,
            p_vote_value: vote_value
        });

        if (error) throw error;

        res.status(200).json({ message: 'Vote registered successfully' });
    } catch (error) {
        console.error('Toggle Comment Vote Error:', error);
        res.status(500).json({ error: 'Failed to register vote.' });
    }
};

export const markProductAsSold = async (req, res) => {
   try {
       const { id } = req.params;
       const { buyer_id } = req.body;

       // 1. Update the product status to 'sold'
       const { data: product, error: updateError } = await supabase
           .from('products')
           .update({ status: 'sold' })
           .eq('id', id)
           .select()
           .single();

       if (updateError) throw updateError;

       // 2. If a buyer was selected from the platform, record the purchase for social proof
       if (buyer_id) {
           const { error: purchaseError } = await supabase
               .from('purchases')
               .insert([{
                   buyer_id: buyer_id,
                   product_id: id
               }]);

           if (purchaseError) console.error("Failed to insert purchase record:", purchaseError);
       }

       res.status(200).json({ message: 'Product marked as sold', product });
   } catch (error) {
       console.error('Mark Sold Error:', error);
       res.status(500).json({ error: 'Failed to mark product as sold.' });
   }
};

export const markProductAsAvailable = async (req, res) => {
   try {
       const { id } = req.params;

       // 1. Update the product status back to 'available'
       const { data: product, error: updateError } = await supabase
           .from('products')
           .update({ status: 'available' })
           .eq('id', id)
           .select()
           .single();

       if (updateError) throw updateError;

       // 2. Remove the purchase record to undo the social proof
       const { error: purchaseError } = await supabase
           .from('purchases')
           .delete()
           .eq('product_id', id);

       if (purchaseError) console.error("Failed to delete purchase record:", purchaseError);

       res.status(200).json({ message: 'Product marked as available', product });
   } catch (error) {
       console.error('Mark Available Error:', error);
       res.status(500).json({ error: 'Failed to mark product as available.' });
   }
};


